-- Create "network_ingresses" table
CREATE TABLE "network_ingresses" ("id" uuid NOT NULL DEFAULT generate_uuidv7(), "organization_id" text NOT NULL, "provider" text NOT NULL DEFAULT 'tailscale', "hostname" text NOT NULL DEFAULT 'gram-mcp', "credential_kind" text NOT NULL, "auth_key_enc" text NULL, "oauth_client_id" text NULL, "oauth_client_secret_enc" text NULL, "tags" text[] NOT NULL DEFAULT '{}', "enabled" boolean NOT NULL DEFAULT true, "private_network_only" boolean NOT NULL DEFAULT false, "identity_required" boolean NOT NULL DEFAULT true, "status" text NOT NULL DEFAULT 'pending', "network_name" text NULL, "dns_name" text NULL, "node_id" text NULL, "last_error" text NULL, "last_seen_at" timestamptz NULL, "connected_since" timestamptz NULL, "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(), "updated_at" timestamptz NOT NULL DEFAULT clock_timestamp(), "deleted_at" timestamptz NULL, "deleted" boolean NOT NULL GENERATED ALWAYS AS (deleted_at IS NOT NULL) STORED, PRIMARY KEY ("id"), CONSTRAINT "network_ingresses_credential_kind_check" CHECK (credential_kind <> ''::text), CONSTRAINT "network_ingresses_hostname_check" CHECK (hostname <> ''::text), CONSTRAINT "network_ingresses_provider_check" CHECK (provider <> ''::text));
-- Create index "network_ingresses_organization_id_key" to table: "network_ingresses"
CREATE UNIQUE INDEX "network_ingresses_organization_id_key" ON "network_ingresses" ("organization_id") WHERE (deleted IS FALSE);
-- Create "network_node_state" table
CREATE TABLE "network_node_state" ("ingress_id" uuid NOT NULL, "key" text NOT NULL, "value" bytea NOT NULL, "created_at" timestamptz NOT NULL DEFAULT clock_timestamp(), "updated_at" timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY ("ingress_id", "key"));
